/**
 * DEVELOPMENT corpus for request authority (IR-107 Unit 2). **This is not a holdout.**
 *
 * Written blind: two generators were given the five operation contracts in prose, the product
 * framing and the legal guardrails, and were forbidden to read requestAuthority.ts, its
 * construction table, subjectAuthority.ts, requestFrame.ts, or any file matching *holdout*.
 * That is what makes it a fair picture of how people actually ask; it is not what would make it
 * evidence.
 *
 * The distinction matters and is easy to lose. This corpus may be inspected, iterated against and
 * fitted to — that is its job — and the moment it is, it stops being able to tell anyone whether
 * the parser generalises. The frozen corpora (requestAuthorityHoldout, adviceGuardrailHoldout,
 * adviceGuardrailHoldout2) stay sealed until the implementation is frozen and are then run once.
 *
 * 500 cases: 300 answerable, 60 per operation, EN/KO evenly split; 200 negative controls across ten
 * labels. The negative labels are the point of the design — a parser can raise coverage by becoming
 * permissive, and only the controls can tell the difference.
 */

export type DevelopmentExpectation = "ANSWERABLE" | "REFUSED";

export interface DevelopmentCase {
  id: string;
  language: "EN" | "KO";
  query: string;
  expected: DevelopmentExpectation;
  /** For answerable cases the operation asked for; for controls, the reason it must be refused. */
  operation: string;
  note: string;
}

